type Data={access?:{role:'owner'|'editor';grantId:string}|null;sharing?:{enabled:boolean};mode:'preview'|'beta';capabilities:{previewControls:boolean;connectedServices:boolean};workspace:Workspace|null;revision:number;policy:(Policy&{access:{allowed:boolean;reason:string};synthetic:boolean})|null;updatedAt?:string;result?:Record<string,unknown>};
async function readWorkspace(){const r=await fetch('/api/family',{cache:'no-store'}),d=await r.json() as Data&{error?:string};if(!r.ok)throw new Error(d.error??'Could not open your workspace.');return d;}
