  useEffect(()=>{if(!retryAt)return;const tick=()=>setRetrySeconds(Math.max(0,Math.ceil((retryAt-Date.now())/1000)));const id=window.setInterval(tick,1000);return()=>window.clearInterval(id);},[retryAt]);
  const nav=(next:string,id='')=>{setView(next);setEventId(id);setShowHidden(false);const q=id?`event=${encodeURIComponent(id)}`:`view=${next}`;history.pushState(null,'',`/app?${q}`);window.scrollTo(0,0);};
  const submit=useCallback(async(body:Record<string,unknown>,onSuccess?:(data:Data)=>void):Promise<Data|null>=>{if(inFlight.current)return null;if(current.current?.sharing?.enabled&&!pendingMarker.current){try{const id=crypto.randomUUID();markPending(id);pendingMarker.current=id;}catch{setError('This browser cannot track unconfirmed work safely. Enable site storage before saving. Nothing was sent.');return null;}}inFlight.current=true;setSaving(true);setSaved('');setRetryAt(0);setRetrySeconds(0);setError('');setConflict(false);setRetryBody(body);pendingActive.current=true;retrySuccess.current=onSuccess;try{const r=await fetch('/api/family',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json() as Data&{error?:string};if(!r.ok){if(r.status===403&&d.error?.startsWith('Access changed.'))setAccessEnded(true);setConflict(r.status===409);if(r.status===429){const seconds=Math.max(1,Number(r.headers.get('Retry-After'))||60);setRetryAt(Date.now()+seconds*1000);setRetrySeconds(seconds);}throw new Error(d.error??'Nothing was saved.');}setCurrent(d);if(body.onboard)window.scrollTo(0,0);setRetryBody(null);pendingActive.current=false;clearEntryMarker();retrySuccess.current=undefined;setSaved(body.deleteWorkspace?'The selected workspace was deleted.':'Saved workspace');onSuccess?.(d);return d;}catch(e){setError(e instanceof TypeError?'Connection lost. This change has not been confirmed. Retry when connected.':e instanceof Error?e.message:'This change has not been confirmed. Try again.');return null;}finally{setSaving(false);inFlight.current=false;}},[setCurrent,clearEntryMarker]);
